    contentHtml: `<p>자미두수의 핵심은 명반(命盤)이며, 그 명반을 구성하는 가장 중요한 틀이 바로 12궁(十二宮)이다. 12궁은 인간의 일생 전체를 12개의 영역으로 나누어 보여주는 인생 지도라고 할 수 있다.</p>
<p>많은 초보자는 별의 의미부터 배우려 하지만, 실제 고수들은 먼저 12궁의 구조를 완벽하게 이해한다. 궁을 이해하지 못하면 어떤 별이 들어와도 정확한 해석은 불가능하기 때문이다.</p>
<h2>자미두수의 12궁이란?</h2>
<p>12궁은 인생의 모든 분야를 각각 담당하는 열두 개의 공간이다. 각 궁에는 여러 개의 주성(主星), 보조성, 사화(化祿·化權·化科·化忌)가 배치되며, 그 조합이 개인의 운명과 성향을 만들어낸다.</p>
<p>쉽게 말하면 궁(宮)은 인생의 무대, 별(星)은 배우, 사화(四化)는 배우의 역할 변화다. 즉, 궁이 무대이고 별이 그 무대에서 연기하는 배우다. 그래서 같은 자미성이라도 어느 궁에 있느냐에 따라 의미가 완전히 달라진다.</p>
<h2>12궁의 기본 구조</h2>
<p>자미두수의 12궁은 다음과 같다: 명궁(命宮)·형제궁(兄弟宮)·부부궁(夫妻宮)·자녀궁(子女宮)·재백궁(財帛宮)·질액궁(疾厄宮)·천이궁(遷移宮)·노복궁(奴僕宮)·관록궁(官祿宮)·전택궁(田宅宮)·복덕궁(福德宮)·부모궁(父母宮).</p>
<p>이 12궁은 단순한 목록이 아니라 서로 긴밀하게 연결되어 있으며, 하나의 궁을 해석할 때는 반드시 대응궁과 삼합궁을 함께 살펴야 한다.</p>
<h3>① 명궁(命宮) — 인생의 중심</h3>
<p>명궁은 자미두수에서 가장 중요한 궁이다. 이곳은 성격·기질·가치관·재능·삶의 방향·운명의 기본 구조를 나타낸다. 사주에서 일간(日干)이 중심이라면, 자미두수에서는 명궁이 중심이다. 명궁이 강하면 인생의 중심축이 흔들리지 않는다. 반대로 명궁이 약하면 환경의 영향을 많이 받는다. 명궁의 심화 해석은 <a href="/insights/ziwei-minggong/">명궁 해석 가이드</a>에서 다룹니다.</p>
<h3>② 형제궁(兄弟宮)</h3>
<p>형제궁은 단순히 형제자매만 의미하지 않는다. 현대 해석에서는 형제·친구·동료·협력자·인간관계 전체를 나타낸다. 좋은 별이 있으면 평생 귀인을 많이 만나고, 흉성이 많으면 인간관계에서 갈등이 잦다.</p>
<h3>③ 부부궁(夫妻宮)</h3>
<p>배우자의 성격과 결혼생활을 보는 궁이다. 배우자의 성향·결혼 시기·연애 스타일·이혼 가능성·결혼 만족도 등을 종합적으로 분석한다. 실제로 자미두수 상담에서 가장 많이 질문받는 궁 중 하나다.</p>
<h3>④ 자녀궁(子女宮)</h3>
<p>자녀의 숫자만 보는 궁이 아니다. 현대적으로는 자녀운·후배·제자·창작물·사업의 결과물까지 포함한다. 예술가에게는 작품도 자녀궁으로 본다.</p>
<h3>⑤ 재백궁(財帛宮)</h3>
<p>돈을 버는 능력을 보여준다. 여기서 중요한 것은 "얼마를 버느냐"보다 "어떻게 버느냐"다. 사업형·투자형·월급형·전문직형 등의 재물 구조를 확인한다.</p>
<h3>⑥ 질액궁(疾厄宮)</h3>
<p>건강과 질병을 보는 궁이다. 그러나 단순히 병만 보는 것이 아니라 체질·스트레스·정신 건강·생활 습관·사고 위험 등도 함께 해석한다.</p>
<h3>⑦ 천이궁(遷移宮)</h3>
<p>명궁의 맞은편에 위치한다. 외부 세계를 의미하며 사회생활·해외운·여행·이사·대인관계·사회적 평판 등을 본다. 명궁이 '나'라면 천이궁은 '세상이 나를 어떻게 보는가'다.</p>
<h3>⑧ 노복궁(奴僕宮)</h3>
<p>예전에는 하인궁이라 불렸지만 오늘날에는 부하직원·직원·고객·협력사·팀원·비즈니스 네트워크를 의미한다. 사업가에게 매우 중요한 궁이다.</p>
<h3>⑨ 관록궁(官祿宮)</h3>
<p>직업과 사회적 성취를 나타낸다. 직업 적성·승진운·사회적 명예·직장운·리더십·직업 변화 등을 본다. 명궁과 함께 반드시 분석하는 핵심 궁이다.</p>
<h3>⑩ 전택궁(田宅宮)</h3>
<p>부동산만 의미하지 않는다. 집·가족환경·재산·상속·투자 자산·거주 환경까지 모두 포함한다. 현대에는 자산관리 능력도 함께 해석한다.</p>
<h3>⑪ 복덕궁(福德宮)</h3>
<p>행복의 크기를 보여주는 궁이다. 부자가 행복한 것은 아니다. 복덕궁은 마음의 여유·정신적 만족·취미·종교·삶의 질·스트레스 해소 능력 등을 나타낸다. 고수들은 재백궁보다 복덕궁을 더 중요하게 보기도 한다.</p>
<h3>⑫ 부모궁(父母宮)</h3>
<p>부모와의 관계뿐 아니라 윗사람·스승·상사·후원자·사회적 보호를 의미한다. 좋은 별이 있으면 평생 귀인의 도움을 많이 받는다.</p>
<h2>12궁은 서로 연결되어 있다</h2>
<p>자미두수에서 가장 중요한 원칙은 궁은 절대로 독립적으로 해석하지 않는다는 것이다. 관록궁이 아무리 좋아도 재백궁이 약하면 돈으로 연결되지 않을 수 있다. 반대로 재백궁이 강해도 관록궁이 약하면 직업보다 투자나 사업으로 돈을 버는 경우가 많다. 또한 명궁이 강하고 천이궁도 강하면 사회적으로 인정받는 사람이 될 가능성이 높다.</p>
<p>즉, 12궁은 하나의 네트워크이며, 별 하나보다 궁과 궁의 관계를 읽는 것이 자미두수의 핵심이다.</p>
<h2>12궁 해석의 핵심 원칙</h2>
<p>자미두수 고수들은 다음과 같은 순서로 명반을 읽는다.</p>
<ul>
<li>명궁으로 기본 성향을 파악한다.</li>
<li>신궁(身宮)을 통해 실제 행동 방식을 확인한다.</li>
<li>관록궁과 재백궁으로 직업과 재물 구조를 분석한다.</li>
<li>부부궁과 자녀궁으로 가족 관계를 살핀다.</li>
<li>천이궁으로 사회적 활동과 외부 운을 본다.</li>
<li>복덕궁으로 삶의 만족도와 정신적 행복을 확인한다.</li>
<li>사화와 대운·세운을 함께 검토하여 시간의 흐름에 따른 변화를 해석한다.</li>
</ul>
<p>이러한 절차를 통해 명반을 입체적으로 해석해야만 실제 삶과 높은 일치도를 얻을 수 있다.</p>
<h2>결론</h2>
<p>자미두수의 12궁은 단순히 열두 개의 영역을 나열한 체계가 아니라, 인간 삶 전체를 유기적으로 연결하는 구조다. 각 궁은 독립적으로 존재하는 것이 아니라 서로 영향을 주고받으며 하나의 운명 시스템을 형성한다.</p>
<p>따라서 자미두수를 제대로 이해하려면 별의 길흉만 암기하는 것이 아니라, 먼저 12궁이 담당하는 삶의 영역과 궁들 사이의 관계를 깊이 이해해야 한다. 그 위에 주성, 보조성, 사화, 대운과 세운의 흐름을 더하면 비로소 자미두수 명반을 종합적으로 해석할 수 있다.</p>
<p>결국 자미두수에서 12궁은 운명을 읽는 '틀'이며, 별은 그 틀 위에서 작용하는 힘이다. 이 구조를 이해하는 순간 자미두수는 단순한 점술을 넘어 삶의 흐름과 가능성을 분석하는 정교한 해석 체계로 다가오게 된다.</p>`,
