    contentHtml: `<!-- target keyword: 자미두수 사화 | secondary: 화록, 화권, 화과, 화기 -->
<p><strong>자미두수 사화(四化)</strong>는 태어난 해의 천간이 특정 별 네 개에 부여하는 변화 코드로, 화록(化祿)·화권(化權)·화과(化科)·화기(化忌)를 말합니다. 14주성이 명반의 '캐릭터'라면 사화는 그 캐릭터에 걸리는 '버프와 과제'입니다. 어떤 별에 어떤 사화가 붙어 어느 궁에 들어갔는지가, 인생에서 기회가 몰리는 영역과 반복되는 과제가 생기는 영역을 알려줍니다.</p>
<h2>사화가 만들어지는 원리</h2>
<p>사화는 생년 천간(갑·을·병·정·무·기·경·신·임·계)마다 정해진 별 네 개에 배속됩니다. 예를 들어 갑년생은 염정에 화록, 파군에 화권, 무곡에 화과, 태양에 화기가 붙는 식입니다. 그래서 같은 명궁이라도 태어난 해가 다르면 사화의 배치가 달라져 전혀 다른 인생 과제를 갖게 됩니다. 생년 사화 외에 대한·유년의 천간이 만드는 사화도 있어, 시기 해석에서는 여러 겹의 사화를 겹쳐 봅니다.</p>
<h2>화록(祿): 흐르는 인연과 재물</h2>
<p>화록은 순환과 확장의 코드입니다. 화록이 붙은 별은 그 별의 장점이 부드럽게 발휘되고, 사람과 기회와 돈이 자연스럽게 모입니다. 화록이 재백궁에 들면 수입의 파이프라인이 활발하고, 부처궁에 들면 인연 운이 순조로우며, 명궁에 들면 어디서든 호감을 얻는 여유가 생깁니다. 단, 화록은 '흐름'이라 들어온 만큼 나가기도 쉬워 축적은 별개의 과제입니다.</p>
<h2>화권(權): 주도권과 확장 욕구</h2>
<p>화권은 힘과 장악의 코드입니다. 화권이 붙은 별의 영역에서는 책임을 맡고 판을 키우려는 욕구가 강해지고, 실제로 권한이 주어지는 경우가 많습니다. 관록궁의 화권은 승진과 리더십 기회로, 부처궁의 화권은 관계 주도권 경쟁으로 나타날 수 있습니다. 힘이 과하면 독선이 되므로, 화권은 '권한과 책임을 함께 받는 훈련'으로 읽는 것이 실용적입니다.</p>
<h2>화과(科): 명예와 평판, 그리고 귀인</h2>
<p>화과는 인정과 지명도의 코드입니다. 시험·자격·평판·브랜드처럼 이름이 알려져서 얻는 이득이 화과의 영역이며, 위기 때 도와주는 귀인 운도 화과에서 봅니다. 화과가 명궁·관록궁에 들면 실력이 이름으로 전환되는 힘이 강해 전문가·강사·크리에이터 경로에 유리합니다. 화록보다 화려하지 않지만 가장 오래가는 자산을 만드는 사화입니다.</p>
<h2>화기(忌): 집착이 가리키는 성장 과제</h2>
<p>화기는 흔히 '흉하다'고만 알려져 있지만, 정확히는 결핍과 집착의 코드입니다. 화기가 붙은 별의 영역은 자꾸 신경 쓰이고, 애를 써도 마음처럼 되지 않는 느낌을 주며, 그래서 오히려 인생에서 가장 많은 에너지를 쏟게 되는 영역이 됩니다. 재백궁의 화기는 돈에 대한 불안이지만 그 덕에 재무 공부를 하게 만들고, 부처궁의 화기는 관계 집착이지만 그만큼 관계를 진지하게 다루게 만듭니다. 화기는 피할 대상이 아니라 '평생 훈련하게 되는 과목'으로 읽어야 해석이 어긋나지 않습니다.</p>
<h2>사화 실전 적용 순서</h2>
<ul>
<li>내 생년 천간의 사화 네 개가 각각 어느 별에 붙었는지 확인합니다.</li>
<li>그 별들이 들어간 궁을 찾아 기회(록·권·과)의 영역과 과제(기)의 영역을 표시합니다.</li>
<li>사화가 명궁의 삼방사정(관록·재백·천이)에 들어왔는지 보고 인생 골격에 미치는 영향을 가늠합니다.</li>
<li>화기가 있는 궁은 회피가 아니라 관리 루틴을 만드는 방향으로 대응 전략을 세웁니다.</li>
</ul>
<p>사화는 별과 궁을 알아야 제대로 읽힙니다. 별이 낯설다면 <a href="/insights/ziwei-14-main-stars-complete-guide/">14주성 완전 가이드</a>를, 궁 구조가 낯설다면 <a href="/insights/ziwei-life-palaces/">12궁 해석 가이드</a>를 먼저 보세요. 준비가 됐다면 <a href="/ziwei/">자미두수 무료 명반</a>에서 내 사화 배치를 확인하고, 화기 궁의 관리 전략은 <a href="/ziwei-ai/">자미두수 AI</a>와 함께 구체화해볼 수 있습니다.</p>`,
