    slug: "sukuyo-antai",
    title: "업태관계(業胎關係) 완전 가이드 — 함께 성장하며 완성해 가는 인연",
    description: "업태관계는 숙요점에서 서로의 부족한 부분을 비추며 함께 성장하는 관계입니다. 업(業)과 태(胎)의 역할, 연애·결혼·가족·직장·사업에서의 특징과 근·중·원거리별 차이를 정리했습니다.",
    category: "숙요점",
