    description: "숙요점 결혼 궁합은 설렘이 아닌 장기 안정성을 봅니다. 영친·업태·안괴·명성·위성·우쇠 6유형별 결혼 생활 패턴과 결혼 전 점검할 체크리스트를 정리했습니다.",
    category: "숙요점",
    keywords: ["숙요점 결혼", "숙요점 궁합", "27숙 궁합", "결혼 궁합", "영친 결혼", "숙요 결혼 궁합"],
