    contentHtml: `<!-- target keyword: 일간 성격 | secondary: 일간 보는 법, 사주 성격, 십간 -->
<p><strong>일간</strong>은 사주 여덟 글자 중 일주의 천간으로, 명리학에서 '나 자신'을 나타내는 기준점입니다. 갑·을·병·정·무·기·경·신·임·계 열 가지 중 하나이며, 십성도 오행 균형도 모두 이 일간을 기준으로 계산되기 때문에 사주 성격 해석은 반드시 일간 확인에서 시작합니다. 각 일간은 오행(목화토금수)과 음양의 조합으로 고유한 자연물에 비유됩니다.</p>
<h2>왜 하필 일간이 '나'인가</h2>
<p>연주는 조상, 월주는 부모와 사회 환경, 시주는 자녀와 말년을 담당하는 자리라면, 일주는 나와 배우자의 자리입니다. 그중에서도 하늘의 기운인 천간이 드러난 나의 기질을 대표합니다. 나머지 일곱 글자가 일간을 돕는지, 설기하는지, 극하는지에 따라 비겁·식상·재성·관성·인성의 십성이 정해지므로, 일간은 해석 좌표계의 원점이라 할 수 있습니다.</p>
<h2>목(木) 일간: 갑목과 을목</h2>
<p>갑목(甲木)은 하늘로 곧게 자라는 큰 나무입니다. 추진력과 자존심이 강하고 시작에 능하며, 굽히는 것을 싫어해 융통성이 과제로 남습니다. 을목(乙木)은 담쟁이와 화초 같은 유연한 초목입니다. 적응력과 사교성이 뛰어나고 환경을 타고 오르며 성장하지만, 기댈 곳을 찾는 의존성이 함께 나타날 수 있습니다.</p>
<h2>화(火) 일간: 병화와 정화</h2>
<p>병화(丙火)는 만물을 비추는 태양입니다. 밝고 개방적이며 숨김이 없고 주목받는 자리에서 힘을 내지만, 뒷심과 섬세한 마무리가 약점이 되기 쉽습니다. 정화(丁火)는 촛불과 화롯불입니다. 한 점을 오래 데우는 집중력과 따뜻한 배려가 강점이고, 겉은 온화해도 내면의 열정은 병화 못지않게 강합니다.</p>
<h2>토(土) 일간: 무토와 기토</h2>
<p>무토(戊土)는 크고 묵직한 산입니다. 신뢰감과 포용력, 중심을 지키는 뚝심이 있어 사람들이 기대는 유형이지만 변화에는 둔한 편입니다. 기토(己土)는 곡식을 기르는 밭의 흙입니다. 실속 있고 세심하게 사람을 키우는 재주가 있으며, 겉으로 드러나지 않는 속 계산이 깊습니다.</p>
<h2>금(金) 일간: 경금과 신금</h2>
<p>경금(庚金)은 제련 전의 무쇠와 바위입니다. 결단력과 의리, 원칙이 분명하고 한번 정한 것은 밀어붙이지만 그만큼 강대강 충돌이 잦을 수 있습니다. 신금(辛金)은 세공을 마친 보석과 칼날입니다. 예리한 분별력과 완벽주의, 자기 관리가 강점이며 말이 정확한 만큼 날카로움이 상처를 줄 때가 있습니다.</p>
<h2>수(水) 일간: 임수와 계수</h2>
<p>임수(壬水)는 큰 강과 바다입니다. 스케일 큰 지략과 포용력으로 흐름을 만들어내는 유형이지만 방향을 잃으면 범람하듯 산만해질 수 있습니다. 계수(癸水)는 이슬비와 샘물입니다. 감수성과 직관이 섬세하게 스며들며, 조용히 주변을 적시는 영향력을 가집니다.</p>
<h2>일간만으로 단정하면 안 되는 이유</h2>
<p>같은 갑목이라도 주변에 물(인성)이 많아 힘이 넘치는지, 금(관성)에 눌려 있는지에 따라 발현이 정반대가 됩니다. 태어난 계절이 그 오행에 유리한지(조후), 여덟 글자 전체의 오행 분포가 어떤지도 함께 봐야 합니다.</p>
<ul>
<li>일간의 강약: 나를 돕는 글자와 빼는 글자의 세력 비교</li>
<li>계절: 여름의 병화와 겨울의 병화는 온도가 다르다</li>
<li>십성 구성: 기질이 사람·일·돈 중 어디로 흐르는지 — <a href="/insights/ten-gods-beginner-map/">십성 입문 지도</a> 참고</li>
<li>오행 쏠림: 과다·부족의 보정은 <a href="/insights/five-elements-personality-deep-dive/">오행 성격 심화 가이드</a> 참고</li>
</ul>
<p>내 일간이 무엇인지 아직 모른다면 <a href="/saju/">무료 사주풀이</a>에서 명식을 뽑아 일주의 천간부터 확인해보세요. 전체 결과를 읽는 순서는 <a href="/insights/saju-free-guide/">무료 사주풀이 7단계 가이드</a>에 정리되어 있습니다.</p>`,
