    contentHtml: `<!-- target keyword: 십성 | secondary: 십성 해석, 사주 직업운, 정관 편관 -->
<p><strong>십성</strong>(十星)은 사주에서 일간(나)과 나머지 글자들의 오행·음양 관계를 열 가지로 분류한 것입니다. 이 열 가지가 비겁·식상·재성·관성·인성의 다섯 그룹으로 묶이며, 각각 사람·표현·돈·일·공부라는 삶의 역할을 담당합니다. 십성 구성을 읽으면 "나는 어떤 방식으로 일하고, 어떤 관계 패턴을 반복하는가"가 드러납니다.</p>
<h2>십성이 만들어지는 규칙: 오행 5 × 음양 2</h2>
<p>규칙은 단순합니다. 일간과의 오행 관계가 다섯 가지, 각 관계에서 음양이 같은지 다른지로 둘씩 나뉘어 총 열 가지가 됩니다.</p>
<ul>
<li>비견(같은 오행·같은 음양) / 겁재(같은 오행·다른 음양) — 나와 같은 기운, 동료와 경쟁자</li>
<li>식신(내가 생하는 오행·같은 음양) / 상관(내가 생·다른 음양) — 내가 만들어내는 표현과 재능</li>
<li>편재(내가 극하는 오행·같은 음양) / 정재(내가 극·다른 음양) — 내가 다루는 돈과 결과물</li>
<li>편관=칠살(나를 극하는 오행·같은 음양) / 정관(나를 극·다른 음양) — 나를 통제하는 규율과 조직</li>
<li>편인(나를 생하는 오행·같은 음양) / 정인(나를 생·다른 음양) — 나를 채워주는 학문과 보호</li>
</ul>
<p>같은 그룹이라도 음양이 같으면(비견·식신·편재·편관·편인) 기운이 직선적이고, 다르면(겁재·상관·정재·정관·정인) 조율된 형태로 나타난다는 차이가 있습니다.</p>
<h2>직업 관점: 어떤 방식으로 일할 때 힘이 나는가</h2>
<p>비겁이 강하면 독립·자영업·경쟁 환경에서, 식상이 강하면 창작·기획·교육·서비스처럼 표현이 성과가 되는 일에서 힘이 납니다. 재성이 발달하면 영업·사업·재무처럼 결과와 숫자를 다루는 영역, 관성이 발달하면 조직·공직·전문직처럼 책임과 직급이 분명한 구조, 인성이 발달하면 연구·자격·문서 기반의 일이 어울립니다. 핵심은 "십성이 많은 쪽 = 익숙한 작동 방식"으로 읽는 것입니다.</p>
<h2>관계 관점: 누구와의 인연이 크게 작동하는가</h2>
<p>전통 명리에서 재성은 남성 사주의 배우자성, 관성은 여성 사주의 배우자성으로 봅니다. 인성은 어머니와 귀인, 비겁은 형제·동료이자 재물을 나누는 경쟁자, 식상은 아랫사람이며 여성 사주에서는 자녀성이 됩니다. 예컨대 겁재가 강한 해에 동업을 시작한다면 지분과 역할을 문서로 정리하는 식으로, 십성은 관계 리스크 관리에 바로 쓸 수 있습니다.</p>
<h2>실전에서 던질 두 가지 질문</h2>
<p>내 명식에서 가장 많은 십성 그룹은 무엇인가, 그리고 아예 없는 그룹은 무엇인가. 많은 쪽은 강점이자 과잉의 리스크이고, 없는 쪽은 서툴러서 시스템(사람·도구·규칙)으로 보완해야 하는 영역입니다. 이 두 질문만으로도 커리어와 관계 선택의 우선순위가 정리됩니다.</p>
<p>열 가지 각각의 세부 성격과 위치별 해석은 <a href="/insights/ten-gods-beginner-map/">십성 입문 지도</a>에서 하나씩 깊게 다룹니다. 내 십성 구성이 궁금하다면 <a href="/saju/">무료 사주풀이</a>로 명식을 확인하고, 기준점이 되는 일간의 의미는 <a href="/insights/day-master-personality-guide/">일간 성격 가이드</a>에서 이어 읽어보세요.</p>`,
