<p><strong>점성술 출생 차트</strong>(네이탈 차트)는 내가 태어난 순간, 태어난 장소에서 올려다본 하늘을 360도 원판에 그대로 옮긴 지도입니다. 이 지도에서 가장 먼저 읽어야 할 것은 태양궁(정체성)·달궁(감정)·상승궁(첫인상과 삶의 무대)이라는 3축이고, 그다음이 나머지 행성과 12하우스입니다. 이 순서만 알면 처음 보는 차트도 길을 잃지 않습니다.</p>
