<p><strong>태양궁·달궁·상승궁의 차이</strong>는 역할 분담으로 이해하면 정확합니다. 태양궁은 의식적으로 추구하는 정체성, 달궁은 감정 반응과 안정 욕구, 상승궁은 타인에게 비치는 첫인상과 세상에 나가는 태도입니다. 서양 점성술에서 "빅3"라고 부르는 이 세 축만 제대로 조합해도, 별자리 운세 한 줄보다 훨씬 입체적인 자기 이해가 가능합니다.</p>
